import{_ as l,o as t,c as i,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"文書バージョンと保守説明","description":"","frontmatter":{},"headers":[],"relativePath":"ja/99-文档版本与维护说明.md","filePath":"ja/99-文档版本与维护说明.md","lastUpdated":1789183869000}'),r={name:"ja/99-文档版本与维护说明.md"};function o(h,a,d,n,s,u){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="文書バージョンと保守説明" tabindex="-1">文書バージョンと保守説明 <a class="header-anchor" href="#文書バージョンと保守説明" aria-label="Permalink to &quot;文書バージョンと保守説明&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>99</td></tr><tr><td>モジュール</td><td>付録と参考資料</td></tr><tr><td>キーワード</td><td>バージョン管理、保守説明、文書規範、更新ログ、設定保守</td></tr></tbody></table><h2 id="_1-文書体系の概要" tabindex="-1">1. 文書体系の概要 <a class="header-anchor" href="#_1-文書体系の概要" aria-label="Permalink to &quot;1. 文書体系の概要&quot;">​</a></h2><p>アンカー共生文明設定体系は100部のMarkdown文書で構成され、番号は00から99まで、10のモジュールに分かれ、各モジュールに10部の文書がある。文書体系はSPEC.md（文書生成規範）を厳格な制約とし、00-衡元宙宇宙総覧を総綱とし、各モジュールの文書は異なる次元から詳細に展開され、最終的に90-99付録文書によって索引、集約、整理が行われる。文書体系全体は論理的に自己一貫性があり、階層が明確で、相互に参照し合う完全な設定知識ベースを構成している。</p><p>文書体系の設計は「モジュール化、構造化、拡張可能」という三つの原則に従っている。モジュール化とは、各文書が特定のテーマに焦点を当て、独立して完全であることを意味する。構造化とは、すべての文書が統一されたフォーマット規範に従い、読み取りと検索に便利であることを意味する。拡張可能とは、文書体系が十分な拡張空間を予約しており、既存文書の改訂や新しい内容の追加を通じて設定を継続的に改善できることを意味する。</p><h2 id="_2-バージョン番号の規則" tabindex="-1">2. バージョン番号の規則 <a class="header-anchor" href="#_2-バージョン番号の規則" aria-label="Permalink to &quot;2. バージョン番号の規則&quot;">​</a></h2><p>文書体系は「メジャーバージョン番号.マイナーバージョン番号.リビジョン番号」という三段階のバージョン番号規則を採用している:</p><table tabindex="0"><thead><tr><th>バージョン階層</th><th>番号規則</th><th>トリガー条件</th><th>例</th></tr></thead><tbody><tr><td>メジャーバージョン番号</td><td>1から増加</td><td>文書体系に重大な構造調整が発生した場合、例えばモジュールの再区分、コア設定の変更</td><td>v1.0 → v2.0</td></tr><tr><td>マイナーバージョン番号</td><td>0から増加</td><td>ある文書のコア内容に実質的な改訂が行われた場合、または重要な設定内容が追加された場合</td><td>v1.0 → v1.1</td></tr><tr><td>リビジョン番号</td><td>0から増加</td><td>文書の文字修正、フォーマット調整、用語統一などの非実質的な変更</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>現在の文書体系の全体バージョンはv1.0、すなわち初回完全リリースバージョンである。各文書はその文書情報ブロックに自身のバージョン番号を記録し、文書体系の全体バージョン番号は本文書に統一的に記録される。</p><h2 id="_3-文書フォーマット規範の回顧" tabindex="-1">3. 文書フォーマット規範の回顧 <a class="header-anchor" href="#_3-文書フォーマット規範の回顧" aria-label="Permalink to &quot;3. 文書フォーマット規範の回顧&quot;">​</a></h2><p>すべての文書は以下の統一フォーマット規範に従わなければならない（詳細規範はSPEC.mdを参照）:</p><h3 id="_3-1-ファイル命名" tabindex="-1">3.1 ファイル命名 <a class="header-anchor" href="#_3-1-ファイル命名" aria-label="Permalink to &quot;3.1 ファイル命名&quot;">​</a></h3><p>ファイル名のフォーマットは<code>XX-文書タイトル.md</code>であり、XXは00-99の2桁の数字番号、タイトルは中国語、スペースなし。</p><h3 id="_3-2-文書構造" tabindex="-1">3.2 文書構造 <a class="header-anchor" href="#_3-2-文書構造" aria-label="Permalink to &quot;3.2 文書構造&quot;">​</a></h3><p>各文書には以下の構造要素が含まれていなければならない:</p><ol><li><strong>一級タイトル</strong>: 文書タイトル（ファイル名と一致）</li><li><strong>文書情報ブロック</strong>: 番号、所属モジュール、キーワード（3-5個）のテーブル</li><li><strong>本文</strong>: 少なくとも3つの二級タイトルの章、リスト、テーブルなどの構造化要素を使用</li><li><strong>結語</strong>: 簡潔な要約段落</li><li><strong>関連文書</strong>: 2-3部の関連文書の番号と名称をリストアップ</li></ol><h3 id="_3-3-文字数要件" tabindex="-1">3.3 文字数要件 <a class="header-anchor" href="#_3-3-文字数要件" aria-label="Permalink to &quot;3.3 文字数要件&quot;">​</a></h3><p>各文書の本文は800文字以上（タイトルとメタ情報を除く）でなければならない。</p><h3 id="_3-4-執筆スタイル" tabindex="-1">3.4 執筆スタイル <a class="header-anchor" href="#_3-4-執筆スタイル" aria-label="Permalink to &quot;3.4 執筆スタイル&quot;">​</a></h3><ul><li>厳粛で体系的な設定文書のスタイル、百科事典/設定集に類似</li><li>「衡元宙」「アンカー」「共生」などの統一用語を使用</li><li>補充された新しい設定は既存の設定と論理的に自己一貫性がなければならず、「現実を基とし、法則をアップグレード」の原則に適合する</li></ul><h2 id="_4-保守組織と職責" tabindex="-1">4. 保守組織と職責 <a class="header-anchor" href="#_4-保守組織と職責" aria-label="Permalink to &quot;4. 保守組織と職責&quot;">​</a></h2><h3 id="_4-1-設定保守委員会" tabindex="-1">4.1 設定保守委員会 <a class="header-anchor" href="#_4-1-設定保守委員会" aria-label="Permalink to &quot;4.1 設定保守委員会&quot;">​</a></h3><p>設定保守委員会は文書体系の最高保守機関であり、ベテラン設定創作者、論理検証専門家、ユーザー代表で構成される。そのコア職責には以下が含まれる:</p><ul><li>文書体系の全体アーキテクチャと重大改訂方案を審定する</li><li>重大な設定変更を審査し、コア設定との一致性を確保する</li><li>設定紛争を裁決し、権威的な解釈を提供する</li><li>定期的に全面的な設定一致性自己検査を組織する</li><li>文書体系の全体バージョン更新を発布する</li></ul><h3 id="_4-2-モジュール保守者" tabindex="-1">4.2 モジュール保守者 <a class="header-anchor" href="#_4-2-モジュール保守者" aria-label="Permalink to &quot;4.2 モジュール保守者&quot;">​</a></h3><p>各モジュールには1名のモジュール保守者が指定され、そのモジュールの10部の文書の日常保守を担当する。その職責には以下が含まれる:</p><ul><li>モジュール内の文書の設定一致性を追跡する</li><li>モジュール内の文書の改訂申請を審査する</li><li>モジュール内の文書間の相互参照を調整する</li><li>モジュール内容に対するユーザーのフィードバックと提案を収集する</li><li>定期的に設定保守委員会にモジュール保守状況を報告する</li></ul><h3 id="_4-3-文書創作者" tabindex="-1">4.3 文書創作者 <a class="header-anchor" href="#_4-3-文書創作者" aria-label="Permalink to &quot;4.3 文書創作者&quot;">​</a></h3><p>条件を満たすすべての創作者は文書の創作と改訂に参加できる。創作者の職責には以下が含まれる:</p><ul><li>フォーマット規範に従って文書を創作または改訂する</li><li>創作内容が設定矛盾自己チェック表の検査に合格することを確保する</li><li>改訂を提出する際に詳細な改訂説明を添付する</li><li>保守者と委員会の審査作業に協力する</li></ul><h2 id="_5-改訂フロー" tabindex="-1">5. 改訂フロー <a class="header-anchor" href="#_5-改訂フロー" aria-label="Permalink to &quot;5. 改訂フロー&quot;">​</a></h2><h3 id="_5-1-通常改訂フロー" tabindex="-1">5.1 通常改訂フロー <a class="header-anchor" href="#_5-1-通常改訂フロー" aria-label="Permalink to &quot;5.1 通常改訂フロー&quot;">​</a></h3><ol><li><strong>申請提出</strong>: 創作者はモジュール保守者に改訂申請を提出し、改訂文書番号、改訂内容説明、改訂理由を含める。</li><li><strong>モジュール審査</strong>: モジュール保守者は改訂内容を審査し、特にフォーマット規範とモジュール内の一致性を重点的に検査する。審査に合格した後、設定保守委員会に提出する。</li><li><strong>委員会審定</strong>: 設定保守委員会は改訂内容の最終審定を行い、特にモジュール間の一致性とコア設定の一致性を重点的に検査する。</li><li><strong>改訂実行</strong>: 審定に合格した後、モジュール保守者または元の創作者が文書改訂を実行する。</li><li><strong>バージョン更新</strong>: 改訂が完了した後、文書のバージョン番号を更新し、本文書の更新ログに記録する。</li><li><strong>関連同期</strong>: 改訂内容が他の文書に影響を与える場合、関連文書を同期的に改訂しなければならない。</li></ol><h3 id="_5-2-緊急改訂フロー" tabindex="-1">5.2 緊急改訂フロー <a class="header-anchor" href="#_5-2-緊急改訂フロー" aria-label="Permalink to &quot;5.2 緊急改訂フロー&quot;">​</a></h3><p>深刻な設定矛盾やエラーが発見された緊急事態に対しては、緊急改訂フローを起動できる:</p><ol><li><strong>緊急報告</strong>: 発見者は直ちに設定保守委員会に問題を報告する。</li><li><strong>迅速審定</strong>: 委員会は24時間以内に緊急審定を完了し、改訂方案を提供する。</li><li><strong>改訂実行</strong>: 専任者を指定して直ちに改訂を実行する。</li><li><strong>事後補記</strong>: 改訂が完了した後、改訂申請と審査記録を事後的に補記する。</li></ol><h3 id="_5-3-定期全面改訂" tabindex="-1">5.3 定期全面改訂 <a class="header-anchor" href="#_5-3-定期全面改訂" aria-label="Permalink to &quot;5.3 定期全面改訂&quot;">​</a></h3><p>設定保守委員会は毎年1回、文書体系の全面改訂を組織し、以下を含む:</p><ul><li>全面的な設定一致性自己検査</li><li>ユーザーフィードバックの集中処理</li><li>用語体系の統一と更新</li><li>索引文書の同期更新</li><li>文書フォーマットの統一検査と修正</li></ul><h2 id="_6-更新ログ" tabindex="-1">6. 更新ログ <a class="header-anchor" href="#_6-更新ログ" aria-label="Permalink to &quot;6. 更新ログ&quot;">​</a></h2><h3 id="v1-0-初回完全リリース" tabindex="-1">v1.0（初回完全リリース） <a class="header-anchor" href="#v1-0-初回完全リリース" aria-label="Permalink to &quot;v1.0（初回完全リリース）&quot;">​</a></h3><ul><li>全100部の文書の創作とリリースを完了</li><li>文書体系の完全なアーキテクチャとフォーマット規範を確立</li><li>10モジュールの内容カバレッジを完了</li><li>付録索引体系を確立（用語辞典、体系索引、法律索引、編年史、万族名録、人物組織、FAQ、自己チェック表、拡張提案、バージョン説明）</li></ul><h3 id="後続バージョン更新記録エリア" tabindex="-1">後続バージョン更新記録エリア <a class="header-anchor" href="#後続バージョン更新記録エリア" aria-label="Permalink to &quot;後続バージョン更新記録エリア&quot;">​</a></h3><p>（後続バージョンの更新内容はここに追加記録され、バージョン番号、リリース日、主な更新内容の要約を含む）</p><h2 id="_7-文書引用と相互引用規範" tabindex="-1">7. 文書引用と相互引用規範 <a class="header-anchor" href="#_7-文書引用と相互引用規範" aria-label="Permalink to &quot;7. 文書引用と相互引用規範&quot;">​</a></h2><h3 id="_7-1-内部引用" tabindex="-1">7.1 内部引用 <a class="header-anchor" href="#_7-1-内部引用" aria-label="Permalink to &quot;7.1 内部引用&quot;">​</a></h3><p>文書間の相互引用は「文書番号-文書タイトル」のフォーマットを使用し、例えば「文書84『考古協議綱要』を参照」。引用する際には、被引用文書が実際に存在し、番号とタイトルが正しいことを確保しなければならない。</p><h3 id="_7-2-用語引用" tabindex="-1">7.2 用語引用 <a class="header-anchor" href="#_7-2-用語引用" aria-label="Permalink to &quot;7.2 用語引用&quot;">​</a></h3><p>あるコア用語を初めて使用する際には、文書90『用語辞典』の対応する項目を参照するよう注記できる。後続で同じ用語を使用する際には繰り返し注記する必要はない。</p><h3 id="_7-3-外部引用" tabindex="-1">7.3 外部引用 <a class="header-anchor" href="#_7-3-外部引用" aria-label="Permalink to &quot;7.3 外部引用&quot;">​</a></h3><p>設定体系外の現実資料や架空作品を引用する必要がある場合には、出典を注記し、かつこの引用が「現実を基とする」原則の下での参考資料であり、設定体系がその内容を完全に採用していることを代表するものではないことを明確に説明しなければならない。</p><h2 id="_8-品質保証メカニズム" tabindex="-1">8. 品質保証メカニズム <a class="header-anchor" href="#_8-品質保証メカニズム" aria-label="Permalink to &quot;8. 品質保証メカニズム&quot;">​</a></h2><h3 id="_8-1-設定矛盾自己チェック" tabindex="-1">8.1 設定矛盾自己チェック <a class="header-anchor" href="#_8-1-設定矛盾自己チェック" aria-label="Permalink to &quot;8.1 設定矛盾自己チェック&quot;">​</a></h3><p>すべての新規創作と改訂された文書は、文書97『設定矛盾自己チェック表』のすべての検査項目に合格しなければならず、コア設定一致性、モジュール間論理一致性、文書フォーマット規範の三大類、計40項目以上の検査を含む。</p><h3 id="_8-2-相互審査" tabindex="-1">8.2 相互審査 <a class="header-anchor" href="#_8-2-相互審査" aria-label="Permalink to &quot;8.2 相互審査&quot;">​</a></h3><p>各文書は正式リリース前に少なくとも1人の他の創作者の相互審査に合格しなければならず、特にモジュール間の論理一致性と用語統一性を重点的に検査する。</p><h3 id="_8-3-ユーザーフィードバックメカニズム" tabindex="-1">8.3 ユーザーフィードバックメカニズム <a class="header-anchor" href="#_8-3-ユーザーフィードバックメカニズム" aria-label="Permalink to &quot;8.3 ユーザーフィードバックメカニズム&quot;">​</a></h3><p>文書体系にはユーザーフィードバックチャネルが設置されており、ユーザーは以下の方法でフィードバックを提出できる:</p><ul><li>設定矛盾と論理エラーを報告する</li><li>用語の不統一の問題を提出する</li><li>特定の内容の補充または改訂を提案する</li><li>フォーマットと文字のエラーを指摘する</li></ul><p>すべてのフィードバックはモジュール保守者によって分類処理され、重要なフィードバックは設定保守委員会に提出されて審議される。</p><h3 id="_8-4-四半期一致性報告" tabindex="-1">8.4 四半期一致性報告 <a class="header-anchor" href="#_8-4-四半期一致性報告" aria-label="Permalink to &quot;8.4 四半期一致性報告&quot;">​</a></h3><p>設定保守委員会は四半期ごとに1部の『設定一致性報告』を発布し、内容には以下が含まれる:</p><ul><li>本四半期に発見された設定矛盾と処理状況</li><li>本四半期の文書改訂統計</li><li>用語統一の進展</li><li>ユーザーフィードバックの処理状況</li><li>次四半期の保守計画</li></ul><h2 id="_9-文書の保存と配布" tabindex="-1">9. 文書の保存と配布 <a class="header-anchor" href="#_9-文書の保存と配布" aria-label="Permalink to &quot;9. 文書の保存と配布&quot;">​</a></h2><h3 id="_9-1-保存フォーマット" tabindex="-1">9.1 保存フォーマット <a class="header-anchor" href="#_9-1-保存フォーマット" aria-label="Permalink to &quot;9.1 保存フォーマット&quot;">​</a></h3><p>すべての文書はMarkdown（.md）フォーマットで保存され、クロスプラットフォームの可読性とバージョン管理の利便性を確保する。文書はUTF-8エンコーディングを使用し、中国語と特殊文字をサポートする。</p><h3 id="_9-2-ディレクトリ構造" tabindex="-1">9.2 ディレクトリ構造 <a class="header-anchor" href="#_9-2-ディレクトリ構造" aria-label="Permalink to &quot;9.2 ディレクトリ構造&quot;">​</a></h3><p>文書は統一的に<code>anchor-docs/</code>ディレクトリに保存され、ファイル名は<code>XX-文書タイトル.md</code>フォーマットである。SPEC.mdは規範ファイルとして同じディレクトリに保存される。</p><h3 id="_9-3-バージョン管理" tabindex="-1">9.3 バージョン管理 <a class="header-anchor" href="#_9-3-バージョン管理" aria-label="Permalink to &quot;9.3 バージョン管理&quot;">​</a></h3><p>文書のバージョン管理にはGitなどのバージョン管理システムを使用することを推奨し、毎回の改訂提出時に詳細なcommit messageを添付し、改訂内容と理由を記録する。</p><h3 id="_9-4-配布方式" tabindex="-1">9.4 配布方式 <a class="header-anchor" href="#_9-4-配布方式" aria-label="Permalink to &quot;9.4 配布方式&quot;">​</a></h3><p>文書体系は以下の方式で配布できる:</p><ul><li>ZIP圧縮パッケージとしてパッケージ化してダウンロード</li><li>静的ウェブサイトとしてデプロイしてオンライン閲覧</li><li>PDFまたはEPUBフォーマットに変換して読書</li><li>知識ベースシステムにインポートして構造化管理</li></ul><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>文書バージョンと保守説明は、アンカー共生文明設定体系の「管理憲法」である。これは文書体系のバージョン規則、保守組織、改訂フロー、品質保証メカニズム、保存と配布方式を確立し、100部の文書で構成されるこの巨大な設定体系が継続的な成長過程で常に秩序と一致性を維持できることを確保する。優れた設定体系には素晴らしい内容だけでなく、その長期的な健全な発展を保障するための完善された保守メカニズムも必要である。本文書はまさにこのメカニズムのコアキャリアである。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>97-設定矛盾自己チェック表</li><li>90-用語辞典</li><li>00-衡元宙宇宙総覧</li></ul>',77)])])}const b=l(r,[["render",o]]);export{_ as __pageData,b as default};
